head.b:skin:
/* ============================================================
   SM TRADERS — BRAND DESIGN SYSTEM (ORANGE + CHARCOAL)
   Design & Development by SynFusion
   ============================================================ */
:root {
  --orange-primary: #FF6A00;
  --orange-bright:  #FF8A00;
  --orange-deep:    #E65300;
  --orange-glow:    rgba(255, 106, 0, 0.25);
  --orange-soft:    rgba(255, 106, 0, 0.10);

  --charcoal:       #101010;
  --dark:           #171717;
  --soft-black:     #202020;

  --warm-white:     #FFFDFC;
  --bg-light:       #F7F5F2;

  --text-main:      #171717;
  --muted:          #6B6B6B;
  --border:         rgba(23, 23, 23, 0.12);
  --border-dark:    rgba(255, 255, 255, 0.12);

  --radius-sm:      10px;
  --radius-md:      18px;
  --radius-lg:      24px;
  --radius-xl:      32px;

  --shadow-sm:      0 6px 24px rgba(0, 0, 0, 0.05);
  --shadow-md:      0 12px 36px rgba(0, 0, 0, 0.08);
  --shadow-lg:      0 24px 60px rgba(0, 0, 0, 0.14);
  --shadow-orange:  0 10px 30px rgba(255, 106, 0, 0.35);

  --font-main:      'Plus Jakarta Sans', system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;

  --z-header:       100;
  --z-drawer:       500;
  --z-lightbox:     1000;
}

/* Reset & Global Rules */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
html {
  width: 100%;
  max-width: 100%;
  overflow-x: clip;
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
}
body {
  width: 100%;
  min-width: 0;
  overflow-x: clip;
  font-family: var(--font-main);
  background-color: var(--bg-light);
  color: var(--text-main);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img, video {
  display: block;
  max-width: 100%;
  height: auto;
}
svg {
  display: block;
  max-width: 100%;
  max-height: 100%;
  flex-shrink: 0;
}
button, input, select, textarea {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  outline: none;
}
button {
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
a {
  color: inherit;
  text-decoration: none;
}
ul, ol {
  list-style: none;
}
h1, h2, h3, h4, h5, h6 {
  line-height: 1.15;
  letter-spacing: -0.03em;
  font-weight: 800;
  color: var(--text-main);
}
p {
  color: var(--muted);
}

/* Kill Default Blogger Wrappers */
#navbar-iframe, #b-navbar-iframe, .blogger-attribution, .post-feeds, .feed-links,
#Attribution1, .status-msg-wrap, .blog-pager, .quickedit, .widget-item-control,
#outer-wrapper, #content-wrapper, #main-wrapper, #sidebar-wrapper, .blog-posts, .widget, .main {
  margin: 0 !important;
  padding: 0 !important;
  width: auto !important;
  max-width: none !important;
  min-width: 0 !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
}
#navbar-iframe, #b-navbar-iframe, .blogger-attribution, .post-feeds, .feed-links,
#Attribution1, .status-msg-wrap, .blog-pager, .quickedit, .widget-item-control {
  display: none !important;
  height: 0 !important;
  visibility: hidden !important;
}
.sm-cms-hide {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Containers & Section Layouts */
.container {
  width: 100%;
  max-width: 1280px;
  margin-inline: auto;
  padding-inline: clamp(16px, 4vw, 48px);
}
section {
  position: relative;
}
.sec-padding {
  padding-block: clamp(48px, 8vw, 104px);
}
.bg-dark {
  background-color: var(--charcoal);
  color: var(--warm-white);
}
.bg-dark h1, .bg-dark h2, .bg-dark h3, .bg-dark h4 {
  color: var(--warm-white);
}
.bg-dark p {
  color: rgba(255, 255, 255, 0.7);
}
.bg-warm {
  background-color: var(--warm-white);
}

/* Eyebrows & Headings */
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--orange-primary);
}
.eyebrow::before {
  content: "";
  width: 18px;
  height: 2px;
  background: var(--orange-primary);
  border-radius: 2px;
  flex-shrink: 0;
}
.sec-heading {
  font-size: clamp(28px, 4.5vw, 48px);
  margin-top: 10px;
  letter-spacing: -0.035em;
  font-weight: 900;
}
.sec-lead {
  margin-top: 14px;
  font-size: clamp(15px, 1.5vw, 18px);
  max-width: 62ch;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 48px;
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 700;
  font-size: 15px;
  transition: all 0.25s ease;
  border: 1px solid transparent;
  white-space: nowrap;
  touch-action: manipulation;
}
.btn .icon-arr {
  transition: transform 0.25s ease;
  display: inline-block;
}
.btn:hover .icon-arr {
  transform: translateX(4px);
}
.btn-primary {
  background: var(--orange-primary);
  color: #ffffff;
  box-shadow: var(--shadow-orange);
}
.btn-primary:hover {
  background: var(--orange-bright);
  transform: translateY(-2px);
  box-shadow: 0 14px 36px rgba(255, 106, 0, 0.45);
}
.btn-dark {
  background: var(--charcoal);
  color: #ffffff;
}
.btn-dark:hover {
  background: var(--dark);
  transform: translateY(-2px);
}
.btn-ghost {
  background: var(--warm-white);
  border-color: var(--border);
  color: var(--text-main);
}
.btn-ghost:hover {
  border-color: var(--orange-primary);
  color: var(--orange-primary);
  transform: translateY(-2px);
}
.btn-outline-light {
  border-color: rgba(255, 255, 255, 0.25);
  color: #ffffff;
}
.btn-outline-light:hover {
  border-color: var(--orange-primary);
  background: rgba(255, 106, 0, 0.12);
  color: var(--warm-white);
}
.btn-block {
  width: 100%;
}

/* Header Bar */
.navbar-sticky {
  position: sticky;
  top: 0;
  z-index: var(--z-header);
  background: rgba(247, 245, 242, 0.94);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid transparent;
  transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
}
.navbar-sticky.stuck {
  background: rgba(255, 253, 252, 0.98);
  border-bottom-color: var(--border);
  box-shadow: var(--shadow-sm);
}
.navbar-sticky .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 64px;
  padding-inline: 16px;
  gap: 12px;
}
.brand-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}
@media (max-width: 767px) {
  .header-cta-btn {
    display: none !important;
  }
}
.brand-mark {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: linear-gradient(135deg, var(--charcoal), var(--soft-black));
  border: 1px solid rgba(255, 106, 0, 0.3);
  color: var(--orange-primary);
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 15px;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
}
.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1.15;
}
.brand-text strong {
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 0.02em;
  color: var(--text-main);
}
.brand-text span {
  font-size: 10.5px;
  color: var(--orange-primary);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  font-weight: 700;
}

/* Navigation Breakpoint Logic:
   <= 767px: Mobile (Hamburger visible, Desktop links hidden)
   >= 768px: Desktop/Tablet Tab Navigation (Hamburger hidden, Desktop links visible)
*/
.nav-links {
  display: none;
  align-items: center;
  gap: 4px;
  min-width: 0;
}
.nav-links a {
  padding: 8px 12px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-main);
  transition: background 0.2s ease, color 0.2s ease;
  white-space: nowrap;
}
.nav-links a:hover {
  background: var(--orange-soft);
  color: var(--orange-primary);
}
.nav-links a.active {
  background: var(--orange-soft);
  color: var(--orange-primary);
  font-weight: 700;
}

@media (min-width: 768px) and (max-width: 899px) {
  .nav-links {
    display: flex;
    gap: 2px;
  }
  .nav-links a {
    padding: 6px 9px;
    font-size: 13px;
  }
  .navbar-sticky .btn-primary {
    padding: 8px 14px;
    font-size: 13px;
    min-height: 40px;
  }
}

@media (min-width: 900px) and (max-width: 1023px) {
  .nav-links {
    display: flex;
    gap: 4px;
  }
  .nav-links a {
    padding: 8px 12px;
    font-size: 14px;
  }
}

@media (min-width: 1024px) {
  .nav-links {
    display: flex;
    gap: 6px;
  }
  .nav-links a {
    padding: 8px 16px;
    font-size: 14.5px;
  }
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  margin-left: auto;
}
.header-mascot-avatar {
  display: none;
  align-items: center;
  gap: 8px;
  background: var(--warm-white);
  padding: 4px 10px 4px 6px;
  border-radius: 999px;
  border: 1px solid var(--border);
}
.header-mascot-avatar img {
  width: 32px;
  height: 32px;
  object-fit: contain;
}
.header-mascot-avatar span {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--orange-primary);
}

.burger-btn {
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--warm-white);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  flex-shrink: 0;
}
.burger-btn span {
  display: block;
  width: 20px;
  height: 2px;
  background-color: var(--text-main);
  border-radius: 2px;
  transition: transform 0.3s ease, opacity 0.2s ease;
}

@media (min-width: 768px) {
  .burger-btn {
    display: none !important;
  }
}

/* Mobile Navigation Drawer */
.mobile-drawer {
  position: fixed;
  inset: 0;
  z-index: var(--z-drawer);
  background: var(--charcoal);
  color: #ffffff;
  display: flex;
  flex-direction: column;
  padding: 20px clamp(18px, 5vw, 36px) calc(28px + env(safe-area-inset-bottom));
  opacity: 0;
  visibility: hidden;
  transform: translateY(-12px);
  transition: opacity 0.3s ease, transform 0.3s ease, visibility 0.3s;
  overflow-y: auto;
}
.mobile-drawer.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}
.drawer-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
}
.drawer-top strong {
  font-size: 18px;
  font-weight: 900;
  color: #ffffff;
  letter-spacing: 0.05em;
}
.drawer-top strong span {
  color: var(--orange-primary);
}
.drawer-close {
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.2);
  display: grid;
  place-items: center;
  color: #ffffff;
  font-size: 24px;
}
.drawer-nav {
  display: flex;
  flex-direction: column;
  margin-top: 24px;
  flex: 1;
}
.drawer-nav a {
  padding: 16px 4px;
  font-size: 20px;
  font-weight: 700;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #ffffff;
}
.drawer-nav a span {
  color: var(--orange-primary);
  font-size: 16px;
}
.mobile-drawer .btn {
  margin-top: 28px;
}
body.lock-scroll {
  overflow: hidden;
}

/* Hero Section */
.hero-sec {
  padding-block: clamp(32px, 5vw, 64px) clamp(40px, 6vw, 80px);
  background: radial-gradient(70% 50% at 80% 20%, rgba(255, 106, 0, 0.12), transparent 70%),
              radial-gradient(50% 40% at 10% 80%, rgba(16, 16, 16, 0.05), transparent 70%);
}
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
}
.hero-content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}
@media (max-width: 767px) {
  .hero-content {
    align-items: center;
    text-align: center;
  }
}
.synfusion-hero-tag {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 13px;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}
.syn-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--orange-primary);
  box-shadow: 0 0 8px rgba(255, 106, 0, 0.6);
  animation: synPulse 2.5s ease-in-out infinite;
  flex-shrink: 0;
}
@keyframes synPulse {
  0%, 100% {
    transform: scale(1);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.2);
    opacity: 1;
    box-shadow: 0 0 12px rgba(255, 106, 0, 0.95);
  }
}
.hero-content h1 {
  font-size: clamp(32px, 6vw, 60px);
  margin-top: 16px;
  letter-spacing: -0.04em;
  font-weight: 900;
  line-height: 1.1;
}
.hero-content h1 span.highlight-text {
  color: var(--orange-primary);
  display: block;
}
.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}

/* Hero Visual & Mascot Stage */
.hero-visual-stage {
  position: relative;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  padding-bottom: 0px;
}
.hero-glow-bg {
  position: absolute;
  width: 75%;
  height: 75%;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 106, 0, 0.20) 0%, rgba(255, 106, 0, 0) 70%);
  filter: blur(36px);
  z-index: 1;
  pointer-events: none;
}
.wolf-mascot-container {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 380px;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.wolf-mascot-img {
  width: 100%;
  max-width: 100%;
  height: auto;
  max-height: 420px;
  object-fit: contain;
  filter: drop-shadow(0 12px 20px rgba(0, 0, 0, 0.16));
  transition: transform 0.3s cubic-bezier(0.25, 1, 0.5, 1);
}
/* Wolf Ground Composition */
.wolf-ground-stage {
  position: relative;
  width: 85%;
  height: 36px;
  margin-top: -12px;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  z-index: 1;
}
.wolf-ground-glow {
  position: absolute;
  width: 90%;
  height: 100%;
  background: radial-gradient(ellipse at center, rgba(255, 106, 0, 0.22) 0%, rgba(255, 106, 0, 0) 70%);
  border-radius: 50%;
  filter: blur(6px);
}
.wolf-ground-energy {
  position: absolute;
  width: 75%;
  height: 12px;
  background: radial-gradient(ellipse at center, rgba(255, 106, 0, 0.15) 0%, transparent 80%);
  border-top: 1px dashed rgba(255, 106, 0, 0.3);
}
.wolf-ground-shadow {
  position: absolute;
  width: 70%;
  height: 16px;
  background: radial-gradient(ellipse at center, rgba(16, 16, 16, 0.40) 0%, rgba(16, 16, 16, 0) 75%);
  border-radius: 50%;
}

/* Hero Floating Cards */
.float-card {
  position: absolute;
  z-index: 3;
  background: rgba(255, 253, 252, 0.94);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  gap: 10px;
  animation: floatAnim 4s ease-in-out infinite alternate;
  max-width: calc(100vw - 32px);
}
.float-card-1 {
  top: 5%;
  left: -10px;
}
.float-card-2 {
  bottom: 8%;
  right: -10px;
  animation-delay: -2s;
}
@media (max-width: 600px) {
  .float-card {
    display: none !important;
  }
}
.float-card-icon {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--orange-soft);
  color: var(--orange-primary);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.float-card-icon svg {
  width: 18px;
  height: 18px;
}
.float-card-text b {
  display: block;
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--orange-primary);
  font-weight: 800;
}
.float-card-text p {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-main);
}

@keyframes floatAnim {
  0% { transform: translateY(0px); }
  100% { transform: translateY(-8px); }
}

/* Trust Bar */
.trust-bar {
  background: var(--charcoal);
  color: #ffffff;
  padding-block: 28px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}
.trust-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}
.trust-item {
  padding: 12px;
  border-left: 2px solid var(--orange-primary);
}
.trust-item b {
  display: block;
  font-size: 11px;
  letter-spacing: 0.15em;
  color: var(--orange-primary);
  font-weight: 800;
}
.trust-item p {
  margin-top: 4px;
  font-size: 14px;
  font-weight: 700;
  color: #ffffff;
}

/* Services Grid */
.services-top-4 {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  margin-top: 40px;
}
.card-service {
  background: var(--warm-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
  display: flex;
  flex-direction: column;
  gap: 14px;
  position: relative;
  overflow: hidden;
}
.card-service::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--orange-primary), var(--orange-bright));
  opacity: 0;
  transition: opacity 0.3s ease;
}
.card-service:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
  border-color: rgba(255, 106, 0, 0.3);
}
.card-service:hover::before {
  opacity: 1;
}
.service-num {
  font-size: 12px;
  font-weight: 900;
  color: var(--orange-primary);
  letter-spacing: 0.15em;
}
.service-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--orange-soft);
  color: var(--orange-primary);
  display: grid;
  place-items: center;
  flex-shrink: 0;
}
.service-icon svg {
  width: 24px;
  height: 24px;
}
.card-service h3 {
  font-size: 20px;
}
.card-service p {
  font-size: 14.5px;
}
.card-service .card-link {
  margin-top: auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 800;
  font-size: 14px;
  color: var(--orange-primary);
}

/* All Services Expanded Grid */
.services-more-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  margin-top: 24px;
}

/* ============================================================
   SOLAR ROADMAP — SIGNATURE INTERACTIVE SECTION
   ============================================================ */
.solar-roadmap-sec {
  background: var(--bg-light);
  color: var(--text-main);
  padding-block: clamp(48px, 6vw, 88px);
  overflow: hidden;
}
.solar-roadmap-header {
  text-align: center;
  max-width: 680px;
  margin-inline: auto;
}
.solar-roadmap-header .eyebrow {
  justify-content: center;
}
.solar-roadmap-header .eyebrow::before {
  display: none;
}
.solar-roadmap-header h2.sec-heading {
  color: var(--charcoal);
}

/* Desktop Horizontal Roadmap */
.roadmap-desktop-wrap {
  display: none;
  margin-top: 48px;
  position: relative;
  padding-block: 16px 24px;
}
.roadmap-path-svg {
  position: absolute;
  top: 40px;
  left: 5%;
  width: 90%;
  height: 100px;
  z-index: 1;
  pointer-events: none;
}
.roadmap-path-line {
  stroke: rgba(16, 16, 16, 0.12);
  stroke-width: 3;
  stroke-dasharray: 6 6;
  fill: none;
}
.roadmap-path-active {
  stroke: var(--orange-primary);
  stroke-width: 3;
  fill: none;
  transition: stroke-dashoffset 0.5s ease;
}

.roadmap-nodes-container {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.roadmap-node-card {
  background: var(--warm-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 22px;
  cursor: pointer;
  transition: all 0.25s ease;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  box-shadow: var(--shadow-sm);
}
.roadmap-node-card:hover, .roadmap-node-card.active {
  border-color: var(--orange-primary);
  box-shadow: 0 8px 24px rgba(255, 106, 0, 0.15);
  transform: translateY(-3px);
}
.node-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.node-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--orange-soft);
  border: 1.5px solid var(--orange-primary);
  color: var(--orange-primary);
  display: grid;
  place-items: center;
  font-weight: 800;
  font-size: 13px;
}
.node-tag {
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--orange-primary);
  text-transform: uppercase;
}
.roadmap-node-card h3 {
  font-size: 18px;
  font-weight: 800;
  color: var(--charcoal);
}
.roadmap-node-card p {
  font-size: 13.5px;
  color: var(--muted);
  line-height: 1.5;
}

/* Node Visual Energy Flow Box */
.node-flow-box {
  margin-top: 4px;
  background: var(--bg-light);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  font-size: 11.5px;
  font-weight: 700;
  color: var(--text-main);
}
.flow-item {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--text-main);
}
.flow-arrow {
  color: var(--orange-primary);
  font-weight: 800;
}

/* Mobile Vertical Roadmap Timeline */
.roadmap-mobile-timeline {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 28px;
  position: relative;
  padding-left: 20px;
  border-left: 2px solid var(--orange-primary);
}
.mobile-node-card {
  background: var(--warm-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 18px;
  position: relative;
  box-shadow: var(--shadow-sm);
}
.mobile-node-card::before {
  content: "";
  position: absolute;
  left: -26px;
  top: 22px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--orange-primary);
  box-shadow: 0 0 8px var(--orange-primary);
}
.mobile-node-card h3 {
  font-size: 17px;
  font-weight: 800;
  color: var(--charcoal);
}
.mobile-node-card p {
  font-size: 13.5px;
  margin-top: 4px;
  color: var(--muted);
}

/* Process Timeline Section */
.process-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  margin-top: 40px;
}
.process-step-card {
  background: var(--warm-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 24px;
  position: relative;
}
.process-step-num {
  font-size: 12px;
  font-weight: 900;
  color: var(--orange-primary);
  letter-spacing: 0.15em;
}
.process-step-card h3 {
  font-size: 18px;
  margin-top: 6px;
}
.process-step-card p {
  font-size: 14px;
  margin-top: 4px;
}

/* Our Work (Portfolio) */
.portfolio-filters {
  display: flex;
  overflow-x: auto;
  max-width: 100%;
  gap: 8px;
  margin-top: 28px;
  padding-bottom: 8px;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}
.portfolio-filters::-webkit-scrollbar {
  display: none;
}
.filter-btn {
  flex: 0 0 auto;
  padding: 10px 20px;
  border-radius: 999px;
  border: 1px solid var(--border);
  background: var(--warm-white);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.05em;
  transition: all 0.25s ease;
  white-space: nowrap;
}
.filter-btn.active {
  background: var(--charcoal);
  color: #ffffff;
  border-color: var(--charcoal);
}

.portfolio-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 20px;
  margin-top: 28px;
}
.project-card {
  display: block;
  width: 100%;
  max-width: 100%;
  box-sizing: border-box;
  background: var(--warm-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  text-align: left;
}
.project-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.project-thumb {
  width: 100%;
  aspect-ratio: 4/3;
  background: var(--dark);
  position: relative;
  overflow: hidden;
}
.project-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}
.project-card:hover .project-thumb img {
  transform: scale(1.05);
}
.project-content {
  padding: 20px;
}
.project-tag {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.15em;
  color: var(--orange-primary);
  text-transform: uppercase;
}
.project-content h3 {
  font-size: 18px;
  margin-top: 6px;
}
.project-content p {
  font-size: 14px;
  margin-top: 6px;
}
.project-card-hidden {
  display: none !important;
}

/* Lightbox */
.lightbox-modal {
  position: fixed;
  inset: 0;
  z-index: var(--z-lightbox);
  background: rgba(16, 16, 16, 0.96);
  display: none;
  flex-direction: column;
  padding: 20px;
}
.lightbox-modal.open {
  display: flex;
}
.lightbox-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #ffffff;
}
.lightbox-header h3 {
  color: #ffffff;
  font-size: 16px;
}
.lightbox-close {
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #ffffff;
  font-size: 24px;
  display: grid;
  place-items: center;
}
.lightbox-body {
  flex: 1;
  display: grid;
  place-items: center;
  padding: 20px 0;
  overflow: hidden;
}
.lightbox-body img {
  max-width: 100%;
  max-height: 75vh;
  border-radius: var(--radius-md);
  object-fit: contain;
}

/* Owner Profiles / About Section */
.owners-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 32px;
}
@media (max-width: 480px) {
  .owners-grid {
    gap: 10px;
  }
}

.owner-card {
  background: var(--warm-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 16px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 12px;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
@media (min-width: 600px) {
  .owner-card {
    flex-direction: row;
    align-items: flex-start;
    padding: 20px;
    gap: 16px;
  }
}
.owner-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}
.owner-portrait-area {
  width: 56px;
  height: 56px;
  min-width: 56px;
  min-height: 56px;
  border-radius: var(--radius-sm);
  overflow: hidden;
  position: relative;
  background: var(--charcoal);
  flex-shrink: 0;
}
.owner-portrait-area img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.owner-initials {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  font-size: 20px;
  font-weight: 900;
  color: var(--orange-primary);
  background: radial-gradient(circle at 50% 30%, rgba(255, 106, 0, 0.25), transparent 70%), var(--charcoal);
}
.owner-info {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.role-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--orange-soft);
  color: var(--orange-primary);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  align-self: flex-start;
}
.owner-info h3 {
  font-size: clamp(15px, 2vw, 18px);
  font-weight: 800;
  color: var(--charcoal);
  line-height: 1.2;
  margin-top: 2px;
}
.owner-company {
  display: none;
}
.owner-info p {
  font-size: 12.5px;
  line-height: 1.45;
  color: var(--muted);
  margin-top: 2px;
}
.owner-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}
.owner-tags span {
  padding: 2px 8px;
  border-radius: 999px;
  border: 1px solid var(--border);
  font-size: 10.5px;
  font-weight: 700;
  color: var(--text-main);
}

/* Contact & Form Section */
.contact-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 36px;
  margin-top: 40px;
}
.contact-info-list {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.contact-info-card {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--radius-md);
  padding: 18px 20px;
}
.contact-info-card b {
  display: block;
  font-size: 11px;
  letter-spacing: 0.15em;
  color: var(--orange-primary);
  text-transform: uppercase;
}
.contact-info-card p {
  margin-top: 4px;
  font-size: 15px;
  color: #ffffff;
}

.form-card {
  background: var(--warm-white);
  border: 1px solid var(--border);
  border-radius: var(--radius-xl);
  padding: clamp(20px, 4vw, 36px);
  box-shadow: var(--shadow-lg);
}
.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}
.form-group label {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--muted);
}
.form-group input, .form-group select, .form-group textarea {
  width: 100%;
  min-height: 48px;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--bg-light);
  font-size: 16px;
  color: var(--text-main);
  transition: border-color 0.2s ease;
}
.form-group textarea {
  min-height: 110px;
  resize: vertical;
}
.form-group input:focus, .form-group select:focus, .form-group textarea:focus {
  border-color: var(--orange-primary);
}
.form-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 16px;
}

/* FAQ Accordion */
.faq-accordion {
  margin-top: 36px;
  border-top: 1px solid var(--border);
}
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 0;
  text-align: left;
  font-size: clamp(16px, 2vw, 19px);
  font-weight: 700;
  gap: 16px;
  color: var(--text-main);
}
.faq-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid var(--border);
  display: grid;
  place-items: center;
  font-size: 18px;
  flex-shrink: 0;
  transition: transform 0.3s ease, background 0.3s ease;
}
.faq-item.open .faq-icon {
  transform: rotate(45deg);
  background: var(--orange-primary);
  color: #ffffff;
  border-color: var(--orange-primary);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.faq-answer p {
  padding-bottom: 20px;
  font-size: 15px;
}

/* Footer */
.footer {
  background: var(--charcoal);
  color: rgba(255, 255, 255, 0.7);
  padding-block: clamp(36px, 5vw, 56px) 32px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}
.footer-main {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.footer-brand .brand-logo {
  gap: 10px;
}
.footer-nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 18px;
}
.footer-nav a {
  color: rgba(255, 255, 255, 0.8);
  font-size: 14px;
  font-weight: 600;
  transition: color 0.2s ease;
}
.footer-nav a:hover {
  color: var(--orange-primary);
}
.footer-action .btn-sm {
  min-height: 40px;
  padding: 8px 18px;
  font-size: 13.5px;
}
.footer-divider {
  height: 1px;
  background: rgba(255, 255, 255, 0.1);
  margin-block: 28px 20px;
}
.footer-bottom {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-size: 13px;
}
.footer-credit {
  display: flex;
  align-items: center;
  gap: 8px;
}
.credit-label {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.5);
}
.credit-brand {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 700;
  color: #ffffff;
  font-size: 13px;
}
.syn-dot-sm {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background-color: var(--orange-primary);
  box-shadow: 0 0 6px rgba(255, 106, 0, 0.8);
  display: inline-block;
}
.footer-copy {
  color: rgba(255, 255, 255, 0.6);
  font-weight: 600;
  letter-spacing: 0.02em;
}

/* Animations & Fallbacks */
.fade-up {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}
.fade-up.in {
  opacity: 1;
  transform: translateY(0);
}

/* Responsive Rules */
@media (min-width: 480px) {
  .form-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 600px) {
  .services-more-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .portfolio-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .process-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 768px) {
  .trust-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .contact-grid {
    grid-template-columns: 1fr 1.2fr;
  }
  .footer-grid {
    grid-template-columns: 1.5fr 1fr 1fr 1fr;
  }
  .owner-card {
    grid-template-columns: 220px minmax(0, 1fr);
  }
}

@media (min-width: 1024px) {
  .header-mascot-avatar {
    display: flex;
  }
  .hero-grid {
    grid-template-columns: 1.1fr 0.9fr;
  }
  .services-top-4 {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .services-more-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .roadmap-desktop-wrap {
    display: block;
  }
  .roadmap-mobile-timeline {
    display: none;
  }
  .process-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
  .portfolio-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .owners-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
  .fade-up {
    opacity: 1;
    transform: none;
  }
  .float-card, .syn-dot {
    animation: none !important;
  }
}

body.script:
//
  (function () {
    "use strict";

    /* Central Site Configuration Object */
    var SM_CONFIG = {
      businessName: "SM Traders",
      whatsapp: "919876543210",
      owners: [
        {
          name: "Mangesh Yendhe",
          role: "OWNER",
          focus: "Electrical &amp; Solar Solutions",
          initials: "MY",
          tags: ["Electrical", "Solar", "Installation"],
          bio: "Hands-on electrical professional leading major electrical installations, rooftop solar projects, and commercial power distribution."
        },
        {
          name: "Omkar Yendhe",
          role: "CO-FOUNDER",
          focus: "Electrical &amp; Solar Solutions",
          initials: "OY",
          tags: ["Electrical", "Solar", "Service"],
          bio: "Co-founding partner overseeing site management, client service coordination, and technical maintenance execution."
        }
      ],
      projects: [
        { title: "Rooftop Solar Installation", category: "solar residential", desc: "Turnkey residential solar panels setup with grid connectivity." },
        { title: "Commercial Power Distribution", category: "electrical commercial", desc: "Main MCB/RCCB distribution board installation for commercial complex." },
        { title: "Full House Wiring Project", category: "electrical residential", desc: "Concealed house wiring with branded copper cables and modular switches." },
        { title: "Commercial LED Lighting Setup", category: "electrical commercial", desc: "Architectural LED lighting layout for retail store." },
        { title: "Solar Inverter Room Wiring", category: "solar commercial", desc: "High-capacity solar inverter and safety SPD box installation." },
        { title: "Inverter & Battery Backup", category: "electrical residential", desc: "Heavy-duty home inverter setup with automated switchover." }
      ],
      faq: [
        { q: "What electrical services does SM Traders provide?", a: "We provide complete electrical installation, concealed house wiring, DB board upgrades, MCB/RCCB protection, inverter setup, LED lighting, and repair services." },
        { q: "Which solar system configuration should I choose?", a: "On-Grid is best for grid-connected homes to reduce electricity bills. Off-Grid is best for remote power independence with batteries. Hybrid offers both grid connection and battery backup." },
        { q: "Do you handle both residential and commercial work?", a: "Yes, we handle residential apartments, independent houses, commercial showrooms, and offices." },
        { q: "How do I request a quote?", a: "You can click 'Get a Quote' or submit the contact form to share your project details via WhatsApp." },
        { q: "Do you provide maintenance and after-sales support?", a: "Yes, we provide routine electrical maintenance, solar panel inspection, and post-installation support." }
      ]
    };

    var $ = function (s, c) { return (c || document).querySelector(s); };
    var $$ = function (s, c) { return Array.prototype.slice.call((c || document).querySelectorAll(s)); };

    function escapeXml(str) {
      return String(str || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function buildWaUrl(msg) {
      var num = SM_CONFIG.whatsapp.replace(/[^0-9]/g, "");
      var text = encodeURIComponent(msg || "Hello SM Traders, I would like to enquire about your services.");
      return "https://wa.me/" + num + "?text=" + text;
    }

    /* Render Leadership Owners */
    function renderOwners() {
      var container = $("#ownersGrid");
      if (!container) return;

      container.innerHTML = SM_CONFIG.owners.map(function (owner) {
        var portraitHtml = '<div class="owner-initials">' + escapeXml(owner.initials) + '</div>';
        var tagsHtml = owner.tags.map(function (t) { return '<span>' + escapeXml(t) + '</span>'; }).join('');

        return '<article class="owner-card fade-up">' +
          '<div class="owner-portrait-area">' + portraitHtml + '</div>' +
          '<div class="owner-info">' +
            '<span class="role-badge">' + escapeXml(owner.role) + '</span>' +
            '<h3>' + escapeXml(owner.name) + '</h3>' +
            '<span class="owner-company">SM TRADERS</span>' +
            '<p>' + escapeXml(owner.bio) + '</p>' +
            '<div class="owner-tags">' + tagsHtml + '</div>' +
          '</div>' +
        '</article>';
      }).join('');
    }

    /* Render Portfolio Projects */
    var currentProjects = [];
    function renderPortfolio() {
      var container = $("#portfolioGrid");
      if (!container) return;

      currentProjects = SM_CONFIG.projects;
      container.innerHTML = currentProjects.map(function (p, index) {
        var svgPlaceholder = '<div style="width:100%;height:100%;box-sizing:border-box;display:flex;flex-direction:column;align-items:center;justify-content:center;background:var(--charcoal);color:rgba(255,255,255,0.8);padding:16px;text-align:center;"><svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" style="stroke:var(--orange-primary);fill:none;stroke-width:1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/></svg><strong style="margin-top:8px;font-size:14px;color:#fff;">' + escapeXml(p.title) + '</strong><span style="font-size:11px;color:var(--orange-primary)">SM TRADERS</span></div>';

        return '<button class="project-card fade-up" type="button" data-index="' + index + '" data-cat="' + escapeXml(p.category) + '">' +
          '<div class="project-thumb">' + svgPlaceholder + '</div>' +
          '<div class="project-content">' +
            '<span class="project-tag">' + escapeXml(p.category.split(' ')[0]) + '</span>' +
            '<h3>' + escapeXml(p.title) + '</h3>' +
            '<p>' + escapeXml(p.desc) + '</p>' +
          '</div>' +
        '</button>';
      }).join('');
    }

    function initPortfolioFilters() {
      var filterBar = $("#portfolioFilters");
      if (!filterBar) return;

      filterBar.addEventListener("click", function (e) {
        var btn = e.target.closest(".filter-btn");
        if (!btn) return;

        $$(".filter-btn", filterBar).forEach(function (b) { b.classList.remove("active"); });
        btn.classList.add("active");

        var filter = btn.getAttribute("data-filter");
        $$("#portfolioGrid .project-card").forEach(function (card) {
          var cat = card.getAttribute("data-cat") || "";
          if (filter === "all" || cat.indexOf(filter) !== -1) {
            card.classList.remove("project-card-hidden");
          } else {
            card.classList.add("project-card-hidden");
          }
        });
      });
    }

    /* Lightbox Modal */
    function openLightbox(index) {
      var modal = $("#lightboxModal");
      if (!modal || !currentProjects[index]) return;

      var p = currentProjects[index];
      var titleEl = $("#lightboxTitle");
      var imgEl = $("#lightboxImg");

      if (titleEl) titleEl.textContent = p.title;
      if (imgEl) {
        imgEl.src = 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="600" viewBox="0 0 800 600"><rect width="800" height="600" fill="#101010"/><text x="400" y="280" fill="#FF6A00" font-family="sans-serif" font-weight="bold" font-size="28" text-anchor="middle">SM TRADERS</text><text x="400" y="320" fill="#ffffff" font-family="sans-serif" font-size="20" text-anchor="middle">' + p.title + '</text></svg>');
      }

      modal.classList.add("open");
      document.body.classList.add("lock-scroll");
    }

    function closeLightbox() {
      var modal = $("#lightboxModal");
      if (!modal) return;
      modal.classList.remove("open");
      document.body.classList.remove("lock-scroll");
    }

    function initLightbox() {
      var grid = $("#portfolioGrid");
      if (grid) {
        grid.addEventListener("click", function (e) {
          var card = e.target.closest(".project-card");
          if (card) {
            var idx = parseInt(card.getAttribute("data-index"), 10) || 0;
            openLightbox(idx);
          }
        });
      }

      var closeBtn = $("#lightboxClose");
      var modal = $("#lightboxModal");
      if (closeBtn) closeBtn.addEventListener("click", closeLightbox);
      if (modal) {
        modal.addEventListener("click", function (e) {
          if (e.target === modal) closeLightbox();
        });
      }
    }

    /* FAQ Accordion */
    function renderFaq() {
      var container = $("#faqAccordion");
      if (!container) return;

      container.innerHTML = SM_CONFIG.faq.map(function (item, i) {
        return '<div class="faq-item">' +
          '<button class="faq-question" type="button" aria-expanded="false">' +
            '<span>' + escapeXml(item.q) + '</span>' +
            '<span class="faq-icon">+</span>' +
          '</button>' +
          '<div class="faq-answer">' +
            '<p>' + escapeXml(item.a) + '</p>' +
          '</div>' +
        '</div>';
      }).join('');

      container.addEventListener("click", function (e) {
        var btn = e.target.closest(".faq-question");
        if (!btn) return;

        var item = btn.parentNode;
        var ans = item.querySelector(".faq-answer");
        var isOpen = item.classList.contains("open");

        $$(".faq-item", container).forEach(function (fi) {
          fi.classList.remove("open");
          fi.querySelector(".faq-question").setAttribute("aria-expanded", "false");
          fi.querySelector(".faq-answer").style.maxHeight = "0px";
        });

        if (!isOpen) {
          item.classList.add("open");
          btn.setAttribute("aria-expanded", "true");
          ans.style.maxHeight = ans.scrollHeight + "px";
        }
      });
    }

    /* Solar Roadmap Interaction */
    function initSolarRoadmap() {
      var nodeOnGrid = $("#nodeOnGrid");
      var nodeOffGrid = $("#nodeOffGrid");
      var nodeHybrid = $("#nodeHybrid");
      var pathActive = $("#desktopPathActive");

      var nodes = [nodeOnGrid, nodeOffGrid, nodeHybrid];
      if (!nodes[0]) return;

      function selectNode(index) {
        nodes.forEach(function (n, idx) {
          if (!n) return;
          if (idx === index) {
            n.classList.add("active");
          } else {
            n.classList.remove("active");
          }
        });

        if (pathActive) {
          if (index === 0) pathActive.style.strokeDashoffset = "600";
          else if (index === 1) pathActive.style.strokeDashoffset = "300";
          else pathActive.style.strokeDashoffset = "0";
        }
      }

      nodes.forEach(function (n, idx) {
        if (!n) return;
        n.addEventListener("click", function () { selectNode(idx); });
        n.addEventListener("mouseenter", function () { selectNode(idx); });
      });
    }

    /* Navigation & Scroll Handler */
    function initNavigation() {
      var burger = $("#burgerBtn");
      var drawer = $("#mobileDrawer");
      var drawerClose = $("#drawerClose");
      var navbar = $("#navbar");

      function toggleDrawer(open) {
        if (!drawer) return;
        drawer.classList.toggle("open", open);
        document.body.classList.toggle("lock-scroll", open);
        if (burger) burger.setAttribute("aria-expanded", open ? "true" : "false");
      }

      if (burger) burger.addEventListener("click", function () { toggleDrawer(true); });
      if (drawerClose) drawerClose.addEventListener("click", function () { toggleDrawer(false); });

      if (drawer) {
        drawer.addEventListener("click", function (e) {
          if (e.target.closest("a")) toggleDrawer(false);
        });
      }

      document.addEventListener("keydown", function (e) {
        if (e.key === "Escape") {
          closeLightbox();
          if (drawer && drawer.classList.contains("open")) toggleDrawer(false);
        }
      });

      window.addEventListener("scroll", function () {
        if (navbar) {
          if (window.scrollY > 20) {
            navbar.classList.add("stuck");
          } else {
            navbar.classList.remove("stuck");
          }
        }
      }, { passive: true });
    }

    /* Contact Form Submission */
    function initContact() {
      var form = $("#contactForm");
      if (!form) return;

      form.addEventListener("submit", function (e) {
        e.preventDefault();
        var name = ($("#inputName") || {}).value || "";
        var phone = ($("#inputPhone") || {}).value || "";
        var service = ($("#selectService") || {}).value || "";
        var location = ($("#inputLocation") || {}).value || "";
        var msg = ($("#inputMsg") || {}).value || "";

        if (!name || !phone) {
          alert("Please enter your name and phone number.");
          return;
        }

        var waText = "Hello SM Traders, I have an enquiry:\n" +
          "Name: " + name + "\n" +
          "Phone: " + phone + "\n" +
          "Service: " + service + "\n" +
          "Location: " + location + "\n" +
          "Message: " + msg;

        window.open(buildWaUrl(waText), "_blank");
      });
    }

    /* Subtle Desktop Parallax */
    function initParallax() {
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
      var stage = $("#heroVisualStage");
      var wolf = $("#wolfMascotImg");
      if (!stage || !wolf || window.innerWidth < 1024) return;

      stage.addEventListener("mousemove", function (e) {
        var rect = stage.getBoundingClientRect();
        var x = (e.clientX - rect.left) / rect.width - 0.5;
        var y = (e.clientY - rect.top) / rect.height - 0.5;
        wolf.style.transform = "translate3d(" + (x * 12) + "px, " + (y * 12) + "px, 0)";
      });

      stage.addEventListener("mouseleave", function () {
        wolf.style.transform = "translate3d(0, 0, 0)";
      });
    }

    /* IntersectionObserver Fade-Up */
    function initScrollReveal() {
      var els = $$(".fade-up");
      if (!("IntersectionObserver" in window)) {
        els.forEach(function (el) { el.classList.add("in"); });
        return;
      }

      var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add("in");
          }
        });
      }, { threshold: 0.01, rootMargin: "50px" });

      els.forEach(function (el) { observer.observe(el); });

      // Immediate reveal for initial viewport elements
      setTimeout(function () {
        els.forEach(function (el) {
          var rect = el.getBoundingClientRect();
          if (rect.top < window.innerHeight + 100) {
            el.classList.add("in");
          }
        });
      }, 50);
    }

    /* Set Year */
    function initYear() {
      var yr = $("#yearSpan");
      if (yr) yr.textContent = new Date().getFullYear();
    }

    /* Boot initialization */
    function init() {
      renderOwners();
      renderPortfolio();
      initPortfolioFilters();
      initLightbox();
      renderFaq();
      initSolarRoadmap();
      initNavigation();
      initContact();
      initParallax();
      initYear();
      initScrollReveal();
    }

    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", init);
    } else {
      init();
    }
  })();
  //
